.mv-popup{width:min(100%,440px);background:#131b2d;border:1px solid #44474e;border-radius:18px;padding:25px;color:#dae2fb;box-shadow:0 25px 80px #0009;animation:mvPop .18s ease-out}
.mv-popup h3{font:700 22px/1.3 'Plus Jakarta Sans',sans-serif;margin:0 0 10px}
.mv-popup p{color:#c5c6cf;line-height:1.6;margin:0 0 20px}
.mv-popup-actions{display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap}
.mv-popup-btn{padding:10px 16px;border-radius:9px;background:#0a458f;color:white;font-weight:600}
.mv-popup-btn.secondary{background:#2c3547}
.mv-popup-icon{width:42px;height:42px;display:grid;place-items:center;border-radius:12px;background:#0a458f;color:#acc7ff;margin-bottom:14px;font-size:22px}
@keyframes mvPop{from{opacity:0;transform:translateY(8px) scale(.98)}to{opacity:1;transform:translateY(0) scale(1)}}
</style>
<div class="mv-popup-backdrop" id="loginPopup" role="dialog" aria-modal="true" aria-labelledby="loginPopupTitle">
 <div class="mv-popup"><div class="mv-popup-icon" id="loginPopupIcon">ⓘ</div><h3 id="loginPopupTitle">Informasi</h3><p id="loginPopupMessage">Pesan</p>
 <div class="mv-popup-actions"><button type="button" class="mv-popup-btn secondary" id="loginPopupCancel">Batal</button><button type="button" class="mv-popup-btn" id="loginPopupOk">Mengerti</button></div></div>
</div>

<script>
    // Popup Box 1: modal informasi/konfirmasi untuk alur login
    const loginPopup = document.getElementById("loginPopup");
    function showLoginPopup(title, message, confirmMode = false, onConfirm = null) {
      document.getElementById("loginPopupTitle").textContent = title;
      document.getElementById("loginPopupMessage").textContent = message;
      document.getElementById("loginPopupCancel").style.display = confirmMode ? "inline-block" : "none";
      document.getElementById("loginPopupOk").textContent = confirmMode ? "Lanjutkan" : "Mengerti";
      loginPopup.classList.add("is-open");
      document.getElementById("loginPopupOk").onclick = () => { loginPopup.classList.remove("is-open"); if (confirmMode && onConfirm) onConfirm(); };
      document.getElementById("loginPopupCancel").onclick = () => loginPopup.classList.remove("is-open");
    }
    loginPopup.addEventListener("click", e => { if (e.target === loginPopup) loginPopup.classList.remove("is-open"); });
    document.getElementById("adminLoginForm").addEventListener("change", e => {
      if (e.target.matches("input")) e.target.dataset.touched = "true";
    });

    // Live Clock Display
    function updateClock() {
      const now = new Date();
      const timeStr = now.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) + ' WIB';
      const el = document.getElementById('clockSync');
      if (el) el.innerText = timeStr;
    }
    setInterval(updateClock, 1000);
    updateClock();

    // Toggle Password Visibility
    function togglePasswordVisibility() {
      const input = document.getElementById('adminPassword');
      const icon = document.getElementById('passwordEyeIcon');
      if (!input || !icon) return;

      if (input.type === 'password') {
        input.type = 'text';
        icon.innerText = 'visibility_off';
      } else {
        input.type = 'password';
        icon.innerText = 'visibility';
      }
    }

    // Micro-interaction: Simulate Admin Authorization Flow
    function simulateAuth() {
      const email = document.getElementById("adminEmail");
      const password = document.getElementById("adminPassword");
      if (!email || !email.value.trim() || !password || !password.value) {
        showLoginPopup("Data belum lengkap", "Masukkan ID admin/email dan kata sandi sebelum melanjutkan.");
        return;
      }
      showLoginPopup("Konfirmasi otorisasi", "Lanjutkan simulasi verifikasi login untuk akun " + email.value.trim() + "?", true, runAuthSimulation);
    }
    function runAuthSimulation() {
      const btn = document.getElementById('submitBtn');
      const btnText = document.getElementById('btnText');
      const btnIcon = document.getElementById('btnIcon');

      if (!btn || !btnText || !btnIcon) return;

      btn.disabled = true;
      btn.classList.add('opacity-75', 'cursor-wait');
      btnText.innerText = 'Memverifikasi login admin...';
      btnIcon.innerText = 'sync';
      btnIcon.classList.add('animate-spin');

      setTimeout(() => {
        btnText.innerText = 'Otorisasi Berhasil. Mengalihkan ke Command Panel...';
        btnIcon.classList.remove('animate-spin');
        btnIcon.innerText = 'check_circle';
        btn.classList.remove('bg-secondary-container');
        btn.classList.add('bg-primary-container', 'text-secondary');

        setTimeout(() => {
          // Normal redirect simulation in real environment
          showLoginPopup('Admin berhasil', 'Login admin berhasil. Anda akan diarahkan ke Dashboard Admin.');
          setTimeout(() => { window.location.href = 'admin.php'; }, 900);
        }, 1200);
      }, 1500);
    }
  </script>
</div></main>


<script>
// BAB 5 PHP: mengirim data form ke server dan menyimpan identitas pada PHP session.
document.addEventListener('submit', async function(e) {
  const form = e.target;
  if (!['registrationForm','userLoginForm','adminLoginForm'].includes(form.id)) return;
  e.preventDefault();
  e.stopImmediatePropagation();
  let payload = new URLSearchParams();
  if (form.id === 'registrationForm') {
    payload.set('action','register');
    payload.set('name', document.getElementById('fullName').value.trim());
    payload.set('contact', document.getElementById('emailPhone').value.trim());
    payload.set('password', document.getElementById('password').value);
    if (payload.get('password') !== document.getElementById('confirmPassword').value) {
      alert('Konfirmasi kata sandi tidak sama.'); return;
    }
    if (!form.querySelector('input[type="checkbox"]').checked) {
      alert('Centang persetujuan terlebih dahulu.'); return;
    }
  } else if (form.id === 'userLoginForm') {
    payload.set('action','login_user');
    payload.set('contact',document.getElementById('userLoginContact').value.trim());
    payload.set('password',document.getElementById('userLoginPassword').value);
  } else {
    payload.set('action','login_admin');
    payload.set('contact',document.getElementById('adminEmail').value.trim());
    payload.set('password',document.getElementById('adminPassword').value);
  }
  try {
    const response = await fetch('auth.php', {method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:payload.toString(),credentials:'same-origin'});
    const result = await response.json();
    if (!response.ok || !result.ok) { alert(result.message || 'Proses gagal.'); return; }
    alert(result.message);
    window.location.href = result.redirect;
  } catch (err) {
    alert('Tidak dapat menghubungi PHP. Jalankan project melalui Laragon/XAMPP, bukan file://.');
  }
}, true);
</script>

</body></html>